  "claims": [
    {
      "claim": "Lisinopril, a zwitterionic ACE-inhibitor diacid sharing the query's primary-amine/carboxylate motif, has about 25% human absorption and is highly soluble, providing affirmative threshold-relevant evidence that this structural class can reach F ≥ 20% despite low passive permeability.",
      "card_ids": ["C111", "C91"]
    },
    {
      "claim": "Low Caco-2/MDCK permeability values for lisinopril do not contradict a high prediction because its human absorption still reaches ~25%, indicating that active transport can overcome poor passive permeability.",
      "card_ids": ["C89", "C122", "C132", "C137", "C111"]
    },
    {
      "claim": "Enalaprilat's negligible PAMPA flux and low intestinal permeability are not directly transferable to the query because enalaprilat lacks the primary amine that is present in the query and in lisinopril, and which is associated with peptide-transporter-mediated absorption.",
      "card_ids": ["C115", "C114", "C111"]
    },
    {
      "claim": "Human ampicillin L1 records (29–43% F) remain additional transferable support that zwitterionic amino-acid/amino-lactam structures can exceed the 20% oral bioavailability threshold.",
      "card_ids": ["C08", "C15", "C19", "C11"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C91", "C111", "C89", "C122", "C132", "C137", "C115", "C114"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No direct PEPT1 or other active-transport assay for the query; lisinopril and related amino-acid drug records are analogs.",
    "The query's exact benzazepinone-lysine hybrid has not been directly tested; benazeprilat-like diacids without a primary amine are poorly absorbed, leaving uncertainty about the contribution of the benzazepinone scaffold.",
    "The estimated logD of -8.18 is a physicochemical prior and may overstate polarity relative to experimental zwitterionic ACE-inhibitor behavior."
  ],
  "decision_summary": "Predicted high (F ≥ 20%) maintained and strengthened to moderate confidence. L4 provides affirmative human absorption evidence for lisinopril (~25%), a close zwitterionic primary-amine diacid analog, plus high solubility; enalaprilat's low permeability is not transferable because it lacks the primary amine. No affirmative F < 20% evidence was introduced."
}

